const lead = $input.item.json;
const slug = (lead.company_name || lead.website || 'lead')
  .toLowerCase()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\..+$/, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 50);
const clientFolderName = slug || `lead-${lead.row_id || Date.now()}`;
return {
  json: {
    ...lead,
    client_slug: clientFolderName,
    client_folder_name: clientFolderName,
    report_id: `${clientFolderName}-${Date.now().toString(36)}`
  }
};

const lead = $('Build Client Slug').item.json;
const input = $input.item.json;

// If the lead already has a Drive folder URL (re-run), reuse it — skip creating a duplicate
const existingUrl = lead.client_folder_url || '';
if (existingUrl.includes('drive.google.com')) {
  const parts = existingUrl.split('folders/');
  const existingId = parts.length > 1 ? parts[1].split('/')[0].split('?')[0] : null;
  if (existingId) {
    return {
      json: {
        ...lead,
        client_folder_id: existingId,
        client_folder_url: existingUrl
      }
    };
  }
}

// New folder was just created by Create Client Folder
return {
  json: {
    ...lead,
    client_folder_id: input.id,
    client_folder_url: input.webViewLink || `https://drive.google.com/drive/folders/${input.id}`
  }
};

const lead = $('Attach Folder ID').item.json;
const homepageHtml = $('Fetch Homepage').item.json.data || $('Fetch Homepage').item.json.body || '';
const contactHtml = $('Fetch Contact Page').item.json.data || $('Fetch Contact Page').item.json.body || '';

function stripHtml(html) {
  if (!html || typeof html !== 'string') return '';
  return html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, ' ')
    .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractTags(html, tag) {
  if (!html) return [];
  const regex = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'gi');
  const matches = [...html.matchAll(regex)];
  return matches.map(m => stripHtml(m[1])).filter(t => t.length > 0).slice(0, 10);
}

function getMeta(html, name) {
  if (!html) return '';
  const patterns = [
    new RegExp(`<meta[^>]+name=["']${name}["'][^>]+content=["']([^"']+)["']`, 'i'),
    new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]+name=["']${name}["']`, 'i'),
    new RegExp(`<meta[^>]+property=["']${name}["'][^>]+content=["']([^"']+)["']`, 'i'),
    new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]+property=["']${name}["']`, 'i')
  ];
  for (const p of patterns) {
    const m = html.match(p);
    if (m) return m[1].trim();
  }
  return '';
}

function extractJsonLd(html) {
  if (!html) return '';
  const regex = /<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  const matches = [...html.matchAll(regex)];
  const texts = [];
  for (const m of matches) {
    try {
      const obj = JSON.parse(m[1]);
      const flatten = (o) => {
        if (!o || typeof o !== 'object') return String(o || '');
        return Object.values(o).map(v => Array.isArray(v) ? v.map(flatten).join(' ') : flatten(v)).join(' ');
      };
      texts.push(flatten(obj));
    } catch(e) {}
  }
  return texts.join(' ').replace(/\s+/g, ' ').trim().slice(0, 1500);
}

const combinedHtml = (homepageHtml + ' ' + contactHtml).toLowerCase();
const homepageText = stripHtml(homepageHtml).slice(0, 4000);
const contactText = stripHtml(contactHtml).slice(0, 2000);
const h1Tags = extractTags(homepageHtml, 'h1');
const h2Tags = extractTags(homepageHtml, 'h2');
const titleMatch = homepageHtml.match(/<title[^>]*>([^<]+)<\/title>/i);
const pageTitle = titleMatch ? titleMatch[1].trim() : '';

const metaDescription = getMeta(homepageHtml, 'description') || getMeta(homepageHtml, 'og:description');
const ogTitle = getMeta(homepageHtml, 'og:title');
const jsonLdText = extractJsonLd(homepageHtml);

const rawCombined = homepageHtml + ' ' + contactHtml;

// === SPA/REACT/VUE COMPATIBLE SIGNAL DETECTION ===
// script src values are always in initial HTML even on React/Vue/SPA sites
const scriptSrcs = [...rawCombined.matchAll(/\bsrc=['"]([^'"]+)['"]/gi)].map(m => m[1]).join(' ').toLowerCase();

// inline script bodies — catches SPA config objects that may contain phone numbers
const allInlineScripts = [...rawCombined.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/gi)]
  .map(m => m[1]).filter(s => s.length > 5).slice(0, 20);
const inlineContent = allInlineScripts.join(' ').slice(0, 10000);

// all href values — reliable source for tel: and mailto: links
const allHrefs = [...rawCombined.matchAll(/\bhref=['"]([^'"]+)['"]/gi)].map(m => m[1].toLowerCase()).join(' ');

// CHAT WIDGET — checks script srcs, full HTML, generic element attributes, and iframes
const chatWidgetPatterns = ['intercom', 'drift.com', 'tawk.to', 'tidio', 'hubspot', 'crisp.chat', 'livechat', 'zendesk', 'olark', 'freshchat', 'chaport', 'smartsupp', 'userlike', 'liveagent', 'purechat', 'chatra', 'jivochat', 'manychat', 'kommunicate', 'helpcrunch', 'gorgias', 'smartagent', 'ylopo', 'boomtown', 'kvcore', 'followupboss', 'sierrainteractive', 'realgeeks', 'boldleads', 'structurely', 'liveperson', 'zopim', 'kayako', 'kustomer', 'webchat', 'web-chat', 'chat.js', 'chat-widget', 'support-chat', 'chatapi', 'aisa.', 'roofstock', 'lofty'];
const genericChatHtml = ['data-chat', 'chat-launcher', 'chat-bubble', 'chat-button', 'chat-icon', 'chat-trigger', 'chat-toggle', 'live-chat', 'chat-widget', 'chat-frame', 'chat-container', 'chat-open', 'chat-popup'];
const hasChatInHtml = genericChatHtml.some(p => combinedHtml.includes(p));
const hasChatIframe = /<iframe[^>]+src=[^>]*(?:chat|support|widget|helpdesk)/i.test(rawCombined);
const hasChatWidget = chatWidgetPatterns.some(w => scriptSrcs.includes(w) || combinedHtml.includes(w)) || hasChatInHtml || hasChatIframe;

// CONTACT FORM — <form> tag OR form service script embed OR mailto: link
const formServicePatterns = ['typeform', 'gravityforms', 'wpcf7', 'wpforms', 'ninja-forms', 'formidable', 'contactform', 'jotform', 'cognito', 'formstack', 'wufoo', 'formspree', 'web3forms', 'getform', 'emailjs', 'hsforms', 'hubspot.com/forms', '123formbuilder', 'netlify.com/api'];
const hasFormTag = /<form[^>]*>/i.test(rawCombined);
const hasFormService = formServicePatterns.some(f => scriptSrcs.includes(f) || combinedHtml.includes(f));
const hasMail = allHrefs.includes('mailto:');
const hasContactForm = hasFormTag || hasFormService || hasMail;

// PHONE — tel: href, phone regex in visible text, phone in SPA inline config, JSON-LD telephone
const phoneRegex = /(?:\+?1[-. ]?)?\(?\d{3}\)?[-. ]?\d{3}[-. ]?\d{4}/;
const telLinkMatch = rawCombined.match(/href=['"]tel:([\+\d\s().\-]+)['"]/i);
const phoneInText = phoneRegex.test(homepageText + ' ' + contactText);
const phoneInInline = phoneRegex.test(inlineContent);
const phoneInJsonLd = combinedHtml.includes('telephone') || phoneRegex.test(jsonLdText);
const hasTelHref = allHrefs.includes('tel:');
const hasPhone = !!(telLinkMatch || phoneInText || phoneInInline || phoneInJsonLd || hasTelHref);

// ONLINE BOOKING — script srcs AND html (covers embedded widgets + visible CTA text)
const bookingPatterns = ['calendly', 'acuityscheduling', 'cal.com', 'oncehub', 'simplybook', 'booksy', 'mindbody', 'schedulicity', 'vagaro', 'setmore', 'appointy', 'squareup.com/appointments', 'book a consultation', 'schedule a call', 'book online', 'book now', 'book a call', 'book a meeting', 'request a showing', 'schedule a showing', 'data-cal-link', 'calendly-inline'];
const hasOnlineBooking = bookingPatterns.some(k => scriptSrcs.includes(k) || combinedHtml.includes(k));

const slowResponsePatterns = [/within 24 hours?/i, /within 48 hours?/i, /1-2 business days?/i, /next business day/i, /respond within/i, /get back to you within/i];
const slowResponseMatch = slowResponsePatterns.find(p => p.test(rawCombined));
const slowResponseEvidence = slowResponseMatch ? rawCombined.match(slowResponseMatch)[0] : null;

const combinedText = [homepageText, contactText, metaDescription, ogTitle, jsonLdText].join(' ');
const totalWords = combinedText.split(/\s+/).filter(Boolean).length;
const isSpa = totalWords < 25;
const lowSignal = homepageHtml.length < 500;

function extractBrandColors(html) {
  if (!html) return [];
  var bad = new Set(['#ffffff','#000000','#333333','#444444','#555555','#666666','#777777','#888888','#999999','#aaaaaa','#bbbbbb','#cccccc','#dddddd','#eeeeee','#f0f0f0','#f5f5f5','#fafafa','#1a1a1a','#222222']);
  function ok(c) { var lc=c.toLowerCase(); if(bad.has(lc)||!/^#[0-9a-f]{6}$/.test(lc))return false; var r=parseInt(lc.slice(1,3),16),g=parseInt(lc.slice(3,5),16),b=parseInt(lc.slice(5,7),16); return r+g+b>80&&!(r>218&&g>218&&b>218); }
  var seen=new Set(); var out=[];
  function add(c){if(!c)return;var lc=c.toLowerCase();if(ok(lc)&&!seen.has(lc)){seen.add(lc);out.push(lc);}}
  var tc=html.match(/theme-color[^#]+(#[0-9a-fA-F]{6})/i); if(tc) add(tc[1]);
  html.replace(/--(?:primary|brand|accent|main-color|site-color|key-color)[^:]*:[^#]*(#[0-9a-fA-F]{6})/gi, function(_,c){add(c);});
  html.replace(/(?:fill|stroke|stop-color)[^(#]{0,10}(#[0-9a-fA-F]{6})/gi, function(_,c){add(c);});
  html.replace(/linear-gradient[(][^)]{0,300}[)]/gi, function(g){g.replace(/#([0-9a-fA-F]{6})/g,function(_,c){add('#'+c);});});
  var stText=''; html.replace(/<style[^>]*>([^]*?)<[/]style>/gi, function(_,s){stText+=s;});
  var freq={}; stText.replace(/#([0-9a-fA-F]{6})(?![0-9a-fA-F])/g,function(_,c){var lc='#'+c.toLowerCase();if(ok(lc))freq[lc]=(freq[lc]||0)+1;});
  Object.entries(freq).sort(function(a,b){return b[1]-a[1];}).slice(0,6).forEach(function(e){add(e[0]);});
  return out.slice(0,4);
}
const brandColors = extractBrandColors(homepageHtml);
const brandColor = brandColors[0] || null;
function resolveUrl(url, base) {
  if (!url) return null;
  if (url.indexOf('http') === 0) return url;
  if (url.indexOf('//') === 0) return 'https:' + url;
  if (url.charAt(0) === '/') {
    var proto = (base || '').indexOf('//');
    var pathStart = proto >= 0 ? (base || '').indexOf('/', proto + 2) : -1;
    return (pathStart > 0 ? (base || '').substring(0, pathStart) : (base || '')) + url;
  }
  var b = base || '';
  if (b.length > 0 && b.charAt(b.length - 1) === '/') b = b.slice(0, -1);
  return b + '/' + url;
}
function isLikelyDemoImage(url) {
  var bad = ['/client', '/partner', '/portfolio', '/testimonial', '/team/', '/case-study', '/showcase', '/sponsor', '/vendor'];
  var u = (url || '').toLowerCase();
  for (var j = 0; j < bad.length; j++) { if (u.indexOf(bad[j]) >= 0) return true; }
  return false;
}
function extractLogoUrl(html, base) {
  if (!html) return null;
  // 1. img with "logo" in src path — most reliable for actual site logo
  var logoSrc = html.match(/<img[^>]+src=["']([^"']*[/\-_]logo[^"']*[.](png|svg|jpg|jpeg|webp)[^"']*)["'][^>]*>/i)
             || html.match(/<img[^>]+src=["']([^"']*logo[^"']+[.](png|svg|jpg|jpeg|webp)[^"']*)["'][^>]*>/i);
  if (logoSrc && logoSrc[1] && !isLikelyDemoImage(logoSrc[1])) return resolveUrl(logoSrc[1], base);
  // 2. img with "logo" in class, id, or alt attribute
  var logoAttr = html.match(/<img[^>]+(?:class|id|alt)=["'][^"']*logo[^"']*["'][^>]+src=["']([^"']+)["'][^>]*>/i)
              || html.match(/<img[^>]+src=["']([^"']+)["'][^>]+(?:class|id|alt)=["'][^"']*logo[^"']*["'][^>]*>/i);
  if (logoAttr && logoAttr[1] && !isLikelyDemoImage(logoAttr[1])) return resolveUrl(logoAttr[1], base);
  // 3. First img inside header or nav — usually the logo
  var hdr = html.match(/<(?:header|nav)[^>]*>[\s\S]{0,800}?<img[^>]+src=["']([^"']+)["'][^>]*>/i);
  if (hdr && hdr[1] && !isLikelyDemoImage(hdr[1])) return resolveUrl(hdr[1], base);
  // 4. apple-touch-icon (fallback — often a generic app icon, not the real logo)
  var atc = html.match(/<link[^>]+rel=["']apple-touch-icon[^"']*["'][^>]+href=["']([^"']+)["'][^>]*>/i)
           || html.match(/<link[^>]+href=["']([^"']+)["'][^>]+rel=["']apple-touch-icon/i);
  if (atc && atc[1]) return resolveUrl(atc[1], base);
  // 5. og:image last resort
  var og = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["'][^>]*>/i)
         || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["'][^>]*>/i);
  if (og && og[1] && /[.](png|svg|jpg|jpeg|webp)/i.test(og[1])) return resolveUrl(og[1], base);
  return null;
}
var logoUrl = extractLogoUrl(homepageHtml, lead.website || '');


// collect which third-party services are in the page source (helps GPT on SPA sites)
const detectedServices = [];
for (const w of chatWidgetPatterns) { if (scriptSrcs.includes(w)) detectedServices.push(w); }
for (const k of bookingPatterns) { if (!k.includes(' ') && scriptSrcs.includes(k)) detectedServices.push(k); }
for (const f of formServicePatterns) { if (scriptSrcs.includes(f)) detectedServices.push(f); }

const scrapedContext = `
COMPANY: ${lead.company_name || 'Unknown'}
WEBSITE: ${lead.website}
PAGE TITLE: ${pageTitle}${ogTitle && ogTitle !== pageTitle ? ' | ' + ogTitle : ''}

META DESCRIPTION:
${metaDescription || 'none found'}

MAIN HEADINGS (H1):
${h1Tags.join(' | ') || 'none found'}

SUB HEADINGS (H2):
${h2Tags.slice(0, 6).join(' | ') || 'none found'}

HOMEPAGE CONTENT (excerpt):
${homepageText.slice(0, 2500) || '(JS-rendered — see structured data below)'}

STRUCTURED DATA (JSON-LD):
${jsonLdText || 'none found'}

CONTACT PAGE CONTENT (excerpt):
${contactText.slice(0, 1500)}

DETECTED AUTOMATION SIGNALS (from page source analysis):
Chat widget: ${hasChatWidget ? 'YES' : 'NO'}
Contact form / email link: ${hasContactForm ? 'YES' : 'NO'}
Phone number: ${hasPhone ? 'YES' : 'NO'}
Online booking tool: ${hasOnlineBooking ? 'YES' : 'NO'}
${detectedServices.length > 0 ? 'Third-party services identified: ' + detectedServices.join(', ') : 'No recognised third-party automation services detected in page source'}
${isSpa ? 'SITE TYPE: JavaScript-rendered (React/Vue SPA). Text content is minimal — page renders client-side. Base your analysis on the detected signals above.' : ''}
`.trim();

return {
  json: {
    ...lead,
    scraped_context: scrapedContext,
    raw_scrape_text: `=== HOMEPAGE ===\n${homepageText}\n\n=== META ===\n${metaDescription}\n\n=== JSON-LD ===\n${jsonLdText}\n\n=== CONTACT PAGE ===\n${contactText}`,
    signals: {
      has_chat_widget: hasChatWidget,
      has_contact_form: hasContactForm,
      has_phone: hasPhone,
      has_online_booking: hasOnlineBooking,
      slow_response_evidence: slowResponseEvidence,
      total_words: totalWords,
      low_signal: lowSignal,
      is_spa: isSpa
    },
    page_title: pageTitle,
    h1_tags: h1Tags,
    brand_color: brandColor,
    brand_colors: brandColors,
    logo_url: logoUrl
  }
};

