const lead = $('Extract Signals & Clean Text').item.json;
const aiResponse = $input.item.json;

function extractJson(raw) {
  if (!raw || typeof raw !== 'string') return raw;
  let s = raw.trim();
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  return s;
}

let audit;
try {
  if (aiResponse.message && aiResponse.message.content) {
    const raw = typeof aiResponse.message.content === 'string'
      ? extractJson(aiResponse.message.content)
      : null;
    audit = raw ? JSON.parse(raw) : aiResponse.message.content;
  } else if (aiResponse.choices && aiResponse.choices[0]) {
    const raw = extractJson(aiResponse.choices[0].message.content);
    audit = JSON.parse(raw);
  } else {
    audit = aiResponse;
  }
} catch (e) {
  return { json: { ...lead, audit_status: 'parse_failed', error: e.message, raw_response: JSON.stringify(aiResponse).slice(0, 500) } };
}

if (!audit.gaps || !Array.isArray(audit.gaps) || audit.gaps.length === 0) {
  return { json: { ...lead, audit_status: 'no_gaps_found', audit_raw: JSON.stringify(audit) } };
}

// Get Jina signals for SPA path (empty if not in that branch)
let jinaData = {};
try { jinaData = $('Build Screenshot URL').item.json; } catch(e) {}

// Remove gaps that contradict confirmed detected signals
const confirmedChat = lead.has_chat_widget === true || jinaData.jina_has_chat === true;
const confirmedBooking = lead.has_online_booking === true || jinaData.jina_has_booking === true;
const confirmedForm = lead.has_contact_form === true;

audit.gaps = audit.gaps.filter(function(gap) {
  var n = (gap.gap_name || '').toLowerCase();
  var f = (gap.fix || '').toLowerCase();
  if (confirmedChat && (n.includes('chatbot') || n.includes('chat bot') || n.includes('live chat') || f.includes('chatbot'))) return false;
  if (confirmedBooking && (n.includes('booking') || n.includes('scheduling') || n.includes('appointment'))) return false;
  if (confirmedForm && (n.includes('contact form') || n.includes('lead capture') || n.includes('lead form'))) return false;
  return true;
});

if (audit.gaps.length === 0) {
  return { json: { ...lead, audit_status: 'no_gaps_found', audit_raw: JSON.stringify(audit) } };
}

// Normalise gap names to standard taxonomy
var gapNameMap = {
  no_chatbot:     'No Chatbot',
  slow_response:  'Slow Lead Response',
  no_after_hours: 'No After-Hours Capture',
  manual_booking: 'Manual Booking Only',
  generic_intake: 'Generic Intake Form',
  no_nurture:     'No Lead Nurture'
};
audit.gaps = audit.gaps.map(function(gap) {
  if (gap.gap_id && gapNameMap[gap.gap_id]) {
    gap.gap_name = gapNameMap[gap.gap_id];
  }
  return gap;
});

const hasPersonalization = audit.specific_observation && audit.specific_observation !== 'null' && audit.specific_observation.length > 5;

return {
  json: {
    ...lead,
    audit_status: 'success',
    has_personalization: hasPersonalization,
    business_type: audit.business_type,
    specialty: audit.specialty,
    specific_observation: audit.specific_observation,
    automation_score: audit.automation_score,
    primary_pain: audit.primary_pain,
    email_hook: audit.email_hook,
    gaps: audit.gaps,
    signals: lead.signals || {
      has_chat_widget: lead.has_chat_widget,
      has_contact_form: lead.has_contact_form,
      has_phone: lead.has_phone,
      has_online_booking: lead.has_online_booking,
      slow_response_evidence: lead.slow_response_evidence,
      total_words: lead.total_words,
      low_signal: lead.low_signal,
      is_spa: lead.is_spa
    },
    jina_has_chat: jinaData.jina_has_chat || lead.jina_has_chat || false,
    jina_has_booking: jinaData.jina_has_booking || lead.jina_has_booking || false,
    audit_full_json: JSON.stringify(audit, null, 2),
    gap_1_name: audit.gaps[0]?.gap_name || '',
    gap_2_name: audit.gaps[1]?.gap_name || '',
    gap_3_name: audit.gaps[2]?.gap_name || ''
  }
};

const data = $input.item.json;

const gapsHtml = (data.gaps || []).map((gap, i) => `
  ${i === 2 ? '<div style="page-break-after:always;height:0;margin:0;padding:0"></div>' : ''}
  <div class="gap-card" style="${i === 2 ? 'margin-top:24px' : ''}">
    <div class="gap-number">0${i + 1}</div>
    <h3>${gap.gap_name}</h3>
    <div class="gap-section"><div class="label">What we found on your site</div><div class="evidence">"${gap.evidence}"</div></div>
    <div class="gap-section"><div class="label">The fix</div><div class="fix">${gap.fix}</div></div>
    <div class="gap-section impact"><div class="label">Estimated impact</div><div class="impact-text">${gap.impact}</div></div>
  </div>
`).join('');

const headerBg = '#0f172a';
const brandPrimary = '#0f172a';
const brandColors = data.brand_colors || (data.brand_color ? [data.brand_color] : []);
const nameStyle = brandColors.length >= 2
  ? '-webkit-background-clip:text;background-clip:text;background-image:linear-gradient(90deg,' + brandColors[0] + ',' + brandColors[1] + ');color:transparent'
  : brandColors.length === 1 ? 'color:' + brandColors[0] : 'color:white';
const bizTypeBadge = data.business_type ? `<div class="biz-type">${data.business_type}</div>` : '';

function buildScoreStory(score, signals, gaps, data) {
  var why;
  if (gaps && gaps.length) {
    var gapNames = gaps.slice(0, 3).map(function(g) { return g.gap_name; });
    why = 'Scored ' + score + '/10 — key gaps: ' + gapNames.join(', ') + '.';
  } else {
    why = 'Scored ' + score + '/10 — some automation is in place, but key gaps remain.';
  }

  var howTo;
  if (gaps && gaps.length) {
    var topFixes = gaps.slice(0, 2).map(function(g) {
      return g.gap_name.replace(/^No /i, '').replace(/^Lack of /i, '').replace(/^Limited /i, '').toLowerCase();
    });
    howTo = 'To reach 10/10: add ' + topFixes.join(' and ') + ', then automate lead follow-up so no inquiry slips through.';
  } else {
    howTo = 'To reach 10/10: set up automated follow-up sequences that nurture every lead without manual effort.';
  }

  return { why: why, howTo: howTo };
}
const scoreStory = buildScoreStory(data.automation_score, data.signals || {}, data.gaps || [], data);


const scoreColor = data.automation_score >= 7 ? '#10b981' : data.automation_score >= 4 ? '#f59e0b' : '#ef4444';
const scoreLabel = data.automation_score >= 7 ? 'Strong' : data.automation_score >= 4 ? 'Average' : 'Major Gaps';

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Automation Audit — ${data.company_name || data.website}</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;line-height:1.5;color:#1a1a1a;background:#f8f9fb;padding:20px}
  .container{max-width:760px;margin:0 auto}
  .header{background-color:${headerBg};background:linear-gradient(135deg,${headerBg} 0%,${headerBg}cc 100%);color:white;padding:32px 40px;border-radius:16px 16px 0 0}
  .header .biz-type{font-size:13px;color:rgba(255,255,255,0.7);margin-bottom:10px;text-transform:capitalize;letter-spacing:0.5px}
  .header h1{font-size:26px;margin-bottom:4px;font-weight:700}
  .header .domain{font-size:15px;color:rgba(255,255,255,0.7)}

  .score-section{background:white;padding:24px 40px;display:flex;align-items:center;gap:24px;border-bottom:1px solid #e5e7eb}
  .score-circle{width:90px;height:90px;border-radius:50%;background:${scoreColor};color:white;display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0}
  .score-circle .num{font-size:32px;font-weight:800;line-height:1}
  .score-circle .out{font-size:13px;opacity:0.85;margin-top:2px}
  .score-info h2{font-size:22px;margin-bottom:8px}
  .score-why{color:#374151;font-size:14px;margin-bottom:8px;line-height:1.6;border-left:3px solid ${brandPrimary};padding-left:12px}
  .score-howto{color:${brandPrimary};font-size:13px;font-weight:600;margin-top:8px}
  .summary{background:white;padding:16px 40px;border-bottom:1px solid #e5e7eb}
  .summary h3{font-size:14px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:12px}
  .summary p{font-size:17px;color:#1f2937}
  .gaps-section{background:white;padding:24px 40px}
  .gaps-section>h2{font-size:20px;margin-bottom:14px}
  .gap-card{border:1px solid #e5e7eb;border-radius:12px;padding:16px 20px;margin-bottom:14px;position:relative}
  .gap-number{position:absolute;top:-12px;left:24px;background:${brandPrimary};color:white;padding:4px 12px;border-radius:20px;font-size:12px;font-weight:700;letter-spacing:1px}
  .gap-card h3{font-size:16px;margin-bottom:10px;margin-top:6px}
  .gap-section{margin-bottom:10px}
  .gap-section .label{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;font-weight:600;margin-bottom:6px}
  .evidence{background:#fef3c7;padding:8px 12px;border-left:3px solid #f59e0b;border-radius:4px;font-style:italic;color:#78350f;font-size:13px}
  .fix{color:#1f2937;font-size:13px}
  .impact-text{background:#d1fae5;padding:8px 12px;border-left:3px solid #10b981;border-radius:4px;color:#064e3b;font-size:13px;font-weight:500}
  .cta{background:linear-gradient(135deg,${brandPrimary} 0%,${brandPrimary}bb 100%);color:white;padding:24px 40px;border-radius:0 0 16px 16px;text-align:center}
  .cta h2{font-size:22px;margin-bottom:8px}
  .cta p{opacity:0.9;margin-bottom:16px;font-size:14px}
  .cta-button{display:inline-block;background:white;color:${brandPrimary};padding:10px 28px;border-radius:8px;text-decoration:none;font-weight:600;font-size:14px}
  .footer{text-align:center;padding:12px;color:#6b7280;font-size:12px}
  .savings-section{background:white;padding:14px 40px;border-top:1px solid #e5e7eb}
  .savings-section>h2{font-size:18px;margin-bottom:6px}
  .savings-sub{color:#6b7280;font-size:12px;margin-bottom:8px}
  .chart-row{display:grid;grid-template-columns:195px 1fr 90px;gap:8px;align-items:center;margin-bottom:8px}
  .chart-label{font-size:13px;font-weight:600;color:#374151}
  .chart-bars{display:flex;flex-direction:column;gap:5px;page-break-inside:avoid;break-inside:avoid}
  .chart-track{background:#f3f4f6;border-radius:4px;height:20px;display:flex;align-items:center}
  .bar{height:100%;border-radius:4px;display:flex;align-items:center;min-width:2px;flex-shrink:0}
  .manual-bar{background:#fca5a5}
  .ai-bar{background:#34d399}
  .bar-val{font-size:11px;font-weight:600;white-space:nowrap;padding:0 6px}
  .chart-saving{font-size:12px;font-weight:700;color:#10b981;text-align:right}
  .cost-callout{display:flex;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:12px;padding:12px;margin-top:10px}
  .cost-item{flex:1;text-align:center;padding:0 12px}
  .cost-num{font-size:22px;font-weight:800;color:#065f46;line-height:1.2}
  .cost-desc{font-size:12px;color:#374151;margin-top:4px}
  .cost-divider{width:1px;background:#bbf7d0;flex-shrink:0}
  @media (max-width:600px){body{padding:20px 12px}.header,.score-section,.summary,.gaps-section,.savings-section,.cta{padding:28px 24px}.score-section{flex-direction:column;text-align:center}.header h1{font-size:24px}.chart-row{grid-template-columns:1fr;gap:6px}.cost-callout{flex-direction:column;gap:16px}.cost-divider{width:100%;height:1px}}
</style>
</head>
<body>
  <div class="container">
    <div class="header">${bizTypeBadge}<h1 style="${nameStyle}">${data.company_name || 'Your Business'}</h1><div class="domain">${data.website}</div></div>
    <div class="score-section"><div class="score-circle"><div class="num">${data.automation_score}</div><div class="out">/ 10</div></div><div class="score-info"><h2>Automation Score: ${scoreLabel}</h2><p class="score-why">${scoreStory.why}</p><p class="score-howto">${scoreStory.howTo}</p></div></div>
    <div class="summary"><h3>The headline</h3><p>${data.email_hook || 'We identified specific opportunities where AI automation could capture leads you\'re currently losing.'}</p></div>
    <div class="gaps-section"><h2>What we found</h2>${gapsHtml}</div>
    <div class="savings-section">
      <h2>The business case for automation</h2>
      <p class="savings-sub">Estimated impact for local service businesses — based on industry averages</p>
      <div style="display:flex;gap:20px;margin-bottom:18px;font-size:12px;color:#6b7280">
        <span><span style="display:inline-block;width:12px;height:12px;background:#fca5a5;border-radius:2px;margin-right:5px;vertical-align:middle"></span>Without AI</span>
        <span><span style="display:inline-block;width:12px;height:12px;background:#34d399;border-radius:2px;margin-right:5px;vertical-align:middle"></span>With AI</span>
      </div>
      <div class="chart-row">
        <div class="chart-label">Lead Response Time</div>
        <div class="chart-bars">
          <div class="chart-track"><div class="bar manual-bar" style="width:100%"><span class="bar-val">Without AI: 4–8 hrs</span></div></div>
          <div class="chart-track"><div class="bar ai-bar" style="width:3%"></div><span style="font-size:11px;font-weight:600;color:#064e3b;padding:0 6px">AI: &lt;60 sec</span></div>
        </div>
        <div class="chart-saving">98% faster</div>
      </div>
      <div class="chart-row">
        <div class="chart-label">Admin Hours / Month</div>
        <div class="chart-bars">
          <div class="chart-track"><div class="bar manual-bar" style="width:100%"><span class="bar-val">Without AI: 15 hrs</span></div></div>
          <div class="chart-track"><div class="bar ai-bar" style="width:13%"><span class="bar-val" style="color:#064e3b">AI: 2 hrs</span></div></div>
        </div>
        <div class="chart-saving">13 hrs saved</div>
      </div>
      <div class="chart-row">
        <div class="chart-label">After-Hours Lead Capture</div>
        <div class="chart-bars">
          <div class="chart-track"><div class="bar manual-bar" style="width:2%"></div><span style="font-size:11px;font-weight:600;color:#374151;padding:0 6px">Without AI: 0%</span></div>
          <div class="chart-track"><div class="bar ai-bar" style="width:100%"><span class="bar-val" style="color:#064e3b">AI: 100%</span></div></div>
        </div>
        <div class="chart-saving">24/7 capture</div>
      </div>
      <div class="chart-row">
        <div class="chart-label">Lead Follow-Up Rate</div>
        <div class="chart-bars">
          <div class="chart-track"><div class="bar manual-bar" style="width:25%"><span class="bar-val">Without AI: 25%</span></div></div>
          <div class="chart-track"><div class="bar ai-bar" style="width:100%"><span class="bar-val" style="color:#064e3b">AI: 100%</span></div></div>
        </div>
        <div class="chart-saving">4x more</div>
      </div>
      <div class="cost-callout">
        <div class="cost-item"><div class="cost-num">$3,600+</div><div class="cost-desc">avg. annual savings on missed leads &amp; admin</div></div>
        <div class="cost-divider"></div>
        <div class="cost-item"><div class="cost-num">156 hrs</div><div class="cost-desc">avg. hours reclaimed per year</div></div>
        <div class="cost-divider"></div>
        <div class="cost-item"><div class="cost-num">3x</div><div class="cost-desc">more leads converted with instant AI follow-up</div></div>
      </div>
    </div>
    <div class="cta"><h2>Want us to build these for you?</h2><p>20-minute walkthrough — we'll show you exactly how each fix works on your site.</p><a href="https://cal.com/{{BOOKING_SLUG}}" class="cta-button">Book a walkthrough →</a></div>
    <div class="footer">Northwind Digital Solutions automates lead capture, booking, and follow-up with chatbots that work 24/7 — so you can focus on closing deals.<br>Ready to automate? Call <strong>+1 (555) 555-0123</strong><br>Audit generated ${new Date().toLocaleDateString('en-CA',{year:'numeric',month:'long',day:'numeric'})}</div>
  </div>
</body>
</html>`;

return {
  json: { ...data, report_html: html },
  binary: {
    data: {
      data: Buffer.from(html, 'utf-8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'audit-report.html'
    }
  }
};

const d = $('Parse & Validate Audit').item.json;
const auditData = {
  meta: {
    company_name: d.company_name,
    website: d.website,
    audited_at: new Date().toISOString(),
    report_id: d.report_id
  },
  business: {
    type: d.business_type,
    specialty: d.specialty
  },
  audit: {
    automation_score: d.automation_score,
    primary_pain: d.primary_pain,
    specific_observation: d.specific_observation,
    email_hook: d.email_hook,
    gaps: d.gaps
  },
  signals: d.signals
};
const jsonStr = JSON.stringify(auditData, null, 2);
return {
  json: { ...$input.item.json },
  binary: {
    data: {
      data: Buffer.from(jsonStr, 'utf-8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'audit-data.json'
    }
  }
};

const d = $('Extract Signals & Clean Text').item.json;
const content = d.raw_scrape_text || '(no scraped content)';
return {
  json: { ...$input.item.json },
  binary: {
    data: {
      data: Buffer.from(content, 'utf-8').toString('base64'),
      mimeType: 'text/plain',
      fileName: 'scraped-content.txt'
    }
  }
};

const d = $('Parse & Validate Audit').item.json;
const folder = $('Attach Folder ID').item.json;

const auditUrl = `https://audit.northwind-digital.example.com/${d.report_id}`;
const firstName = (d.first_name || d.contact_name || '').split(' ')[0] || 'there';
const cleanDomain = d.website.replace(/^https?:\/\//, '').replace(/\/$/, '').replace(/^www\./, '');

const painMap = {
  no_chatbot: 'visitors who land on your site after hours have no way to engage — they bounce',
  slow_response: 'your contact page promises a response time competitors are beating in seconds',
  no_after_hours: 'calls and inquiries outside business hours are going unanswered',
  manual_booking: 'prospects have to call to schedule — which kills conversions',
  generic_intake: 'every lead gets the same form, with no qualification or routing',
  no_nurture: 'leads who don\'t convert immediately get no follow-up'
};
const painPlain = painMap[d.primary_pain] || 'specific spots where you\'re likely losing leads';
const hookLine = d.has_personalization && d.email_hook ? d.email_hook : `Ran a free AI automation audit on ${cleanDomain} this morning.`;
const businessNoun = d.business_type && d.business_type.includes('law') ? 'law firms' : 'realtors';

const subject1 = `quick audit on ${cleanDomain}`;
const body1 = `Hi ${firstName},

${hookLine} Found 3 specific spots where you're likely losing leads to faster competitors.

The biggest one: ${painPlain}.

Full report here (no opt-in, no form): ${auditUrl}

If the findings are useful, I help local ${businessNoun} fix exactly these gaps. Happy to walk you through it on a 20-min call — or just take the report and run with it. No pressure either way.

— Alex Morgan
Northwind Digital Solutions`;

const subject2 = `re: ${cleanDomain} audit`;
const body2 = `Hi ${firstName},

Did the audit make it through? Just want to make sure you actually got it — sometimes these land in promotions.

Link again: ${auditUrl}

The ${(d.gaps || [])[0]?.gap_name || 'main gap'} fix alone usually pays for itself in the first month for ${businessNoun} your size.

— Alex Morgan`;

const subject3 = `closing the loop on ${cleanDomain}`;
const body3 = `Hi ${firstName},

Closing the loop on this — happy to leave the audit up if it's useful, or take it down if it's not the right time.

Either way, no hard feelings. Just don't want to keep cluttering the inbox.

— Alex Morgan`;

const sequenceText = `EMAIL SEQUENCE FOR: ${d.company_name || cleanDomain}
Generated: ${new Date().toLocaleString('en-CA')}
Audit URL: ${auditUrl}
Client folder: ${folder.client_folder_url}

${'='.repeat(60)}
EMAIL 1 — Day 0
${'='.repeat(60)}
Subject: ${subject1}

${body1}

${'='.repeat(60)}
EMAIL 2 — Day 4
${'='.repeat(60)}
Subject: ${subject2}

${body2}

${'='.repeat(60)}
EMAIL 3 — Day 10 (soft close)
${'='.repeat(60)}
Subject: ${subject3}

${body3}
`;

return {
  json: {
    ...$input.item.json,
    audit_url: auditUrl,
    email_subject: subject1,
    email_body: body1,
    email_status: 'ready_to_send'
  },
  binary: {
    data: {
      data: Buffer.from(sequenceText, 'utf-8').toString('base64'),
      mimeType: 'text/plain',
      fileName: 'email-sequence.txt'
    }
  }
};

const lead = $('Extract Signals & Clean Text').item.json;
const jinaRaw = $('Jina Reader Fetch').item.json.data || $('Jina Reader Fetch').item.json.body || $('Jina Reader Fetch').item.json.text || '';

// Detect signals from the FULL content (chat widgets often appear at the very end)
const jinaFull = jinaRaw.trim();
const jinaFullLower = jinaFull.toLowerCase();
const jinaHasChat =
  (jinaFullLower.includes("i'm") && jinaFullLower.includes('assistant')) ||
  jinaFullLower.includes('chat with us') ||
  jinaFullLower.includes('live chat') ||
  jinaFullLower.includes('ask me about') ||
  jinaFullLower.includes('online now') ||
  jinaFullLower.includes('start chat') ||
  (jinaFullLower.includes('hi!') && jinaFullLower.includes('assistant')) ||
  jinaFullLower.includes("hi, i'm") ||
  jinaFullLower.includes("hello! i'm") ||
  (jinaFullLower.includes('how can i help') && jinaFullLower.includes('chat')) ||
  jinaFullLower.includes("i'm here to help") ||
  jinaFullLower.includes('chat bubble');
const jinaHasBooking =
  jinaFullLower.includes('book a consultation') ||
  jinaFullLower.includes('book a call') ||
  jinaFullLower.includes('schedule a') ||
  jinaFullLower.includes('book appointment') ||
  jinaFullLower.includes('calendly') ||
  jinaFullLower.includes('acuity') ||
  jinaFullLower.includes('book now');

// Build GPT content: first 3500 chars (main content) + last 800 chars (footer/chat widget)
const head = jinaFull.slice(0, 3500);
const tail = jinaFull.length > 4300 ? '\n\n[...]\n\n' + jinaFull.slice(-800) : '';
const jinaExcerpt = head + tail;

const cleanUrl = (lead.website || '').replace(/\/$/, '');
const screenshotUrl = 'https://image.thum.io/get/width/1440/crop/9999/' + cleanUrl;

let jinaOverrides = '';
if (jinaHasChat) jinaOverrides += '\n\nCRITICAL OVERRIDE: Jina fully-rendered content CONFIRMS a chat widget / AI assistant IS PRESENT on this page. You MUST NOT list "no chatbot" or any chat-related gap. This overrides all other analysis.';
if (jinaHasBooking) jinaOverrides += '\n\nCRITICAL OVERRIDE: Jina fully-rendered content CONFIRMS a booking or scheduling tool IS PRESENT on this page. You MUST NOT list "no booking" as a gap.';

const userText = jinaExcerpt
  ? 'RENDERED PAGE CONTENT (JavaScript executed, clean text):\n' + jinaExcerpt +
    '\n\n---\nAUTOMATION SIGNALS (from static HTML analysis):\n' + (lead.scraped_context || '') +
    jinaOverrides
  : (lead.scraped_context || 'Website: ' + cleanUrl);

const systemContent = 'Always respond in English only. Do not use French or any other language.\n\nYou are an automation audit specialist for an automation agency (Northwind Digital Solutions) that sells chatbots, booking automations, and lead-nurture flows — across North America (real estate, law, healthcare, home services, finance, and more). Identify the actual business type from the site content — do not default to real estate agent.\n\nThis is a JavaScript-rendered website (React/Vue SPA). You have the fully rendered page text plus a live screenshot. Use both to identify automation gaps.\n\nReturn ONLY a valid JSON object — no markdown, no code fences:\n{"business_type":"label from site content","specialty":"niche or null","specific_observation":"one concrete sentence from screenshot or rendered text or null","automation_score":5,"primary_pain":"no_chatbot|slow_response|no_after_hours|manual_booking|generic_intake|no_nurture","email_hook":"punchy opener under 20 words","gaps":[{"gap_id":"exactly one of: no_chatbot|slow_response|no_after_hours|manual_booking|generic_intake|no_nurture","gap_name":"human label from taxonomy","evidence":"specific proof from rendered text or screenshot","fix":"1-2 sentence fix — never use the word AI","impact":"1 sentence — never use the word AI"},{"gap_id":"...","gap_name":"...","evidence":"...","fix":"...","impact":"..."},{"gap_id":"...","gap_name":"...","evidence":"...","fix":"...","impact":"..."}]}\n\nSTRICT GAP TAXONOMY — use ONLY these 6 gap_id values:\nno_chatbot = No Chatbot (no chat widget found)\nslow_response = Slow Lead Response (24/48 hour response text present)\nno_after_hours = No After-Hours Capture (office hours listed, no after-hours system)\nmanual_booking = Manual Booking Only (call to schedule, no Calendly/Acuity/cal.com)\ngeneric_intake = Generic Intake Form (basic Name/Email/Message form only)\nno_nurture = No Lead Nurture (no newsletter, no follow-up CTAs)\n\nIMPORTANT: ALWAYS trust what you can visually see in the screenshot AND the Jina rendered text. If a chat bubble, live chat button, support widget, messenger icon, or ANY greeting message is visible in the screenshot OR present in the rendered text, the site HAS a chat widget — do NOT use gap_id no_chatbot. Similarly if a booking button is visible or a scheduling tool is mentioned, do not use gap_id manual_booking. CRITICAL OVERRIDE instructions in the user message always take absolute priority over your own visual analysis.\n\nRules: return exactly 3 gaps each with a unique gap_id from the taxonomy; do NOT use the word AI in fix or impact fields; evidence must be specific (not generic); automation_score 1-10 where no chat + no booking = 2-3; primary_pain must match one enum exactly; return only the JSON object.';

return {
  json: {
    ...lead,
    screenshot_url: screenshotUrl,
    jina_content_length: jinaFull.length,
    jina_has_chat: jinaHasChat,
    jina_has_booking: jinaHasBooking,
    openai_vision_request: JSON.stringify({
      model: 'gpt-4o',
      max_tokens: 1200,
      messages: [
        { role: 'system', content: systemContent },
        {
          role: 'user',
          content: [
            { type: 'text', text: userText },
            { type: 'image_url', image_url: { url: screenshotUrl } }
          ]
        }
      ]
    })
  }
};

const html = $('Build Report HTML').item.json.report_html || '';
const slug = $('Build Client Slug').item.json.client_slug || 'report';
return {
  json: {
    ...$('Build Report HTML').item.json,
    client_slug: slug,
    pdf_source: html,
    pdfshift_key: 'YOUR_PDFSHIFT_API_KEY'
  }
};
